const input = $json.body ?? $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || `req_${executionId}`;
const principal = input.principal || input.live_probe?.principal || { twin_id: 'unknown', display_name: 'Unknown' };
const payload = input.live_probe || input;
const isProbe = payload.intent === 'live_probe' || input.intent === 'live_probe';
const safeSlug = (payload.input?.title || input.input?.title || 'knowledge-fabric-probe')
  .toString()
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .slice(0, 72) || 'knowledge-fabric-probe';
const today = new Date().toISOString().slice(0, 10);
const capabilities = payload.context?.expected_capabilities || input.context?.expected_capabilities || [
  'okf_pending_concept_contract',
  'evidence_storage_contract',
  'crud_audit_contract',
  'graph_candidate_trigger_contract',
  'vector_refresh_boundary'
];

const response = {
  envelope_version: input.envelope_version || payload.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'knowledge_fabric_agent',
  status: 'completed',
  output: isProbe ? {
    readiness: 'connected',
    side_effects: 'none',
    capabilities_checked: capabilities
  } : {
    concept_path: `concepts/${principal.twin_id || 'unknown'}/pending/${today}-${safeSlug}.md`,
    evidence_path: `evidence/${principal.twin_id || 'unknown'}/pending/${today}-${safeSlug}.yaml`,
    transcript_path: payload.input?.source_type === 'transcript' ? `transcripts/${principal.twin_id || 'unknown'}/${today}-${safeSlug}.md` : null,
    crud_log_path: `audit/crud/${principal.twin_id || 'unknown'}/${today}.jsonl`,
    review_state: 'pending_review',
    candidate_edges: [
      {
        source: `concept:${safeSlug}`,
        target: 'cluster:pending-review',
        relation_type: 'candidate_member_of_cluster',
        confidence: 0.51
      }
    ],
    graph_curator_trigger: {
      status: 'queued',
      operation: 'derive_candidate_edges',
      target_state: 'candidate'
    },
    vector_refresh: {
      status: 'deferred',
      reason: 'Pending-review concepts are not pushed to trusted vector indexes without review policy approval.'
    }
  },
  trace: {
    stored: true,
    trace_id: `n8n_exec_${executionId}`,
    used_agents: ['knowledge_fabric_agent_shell', 'graph_curator_pending_boundary']
  }
};

return [{ json: response }];
